document.getElementById('ok').addEventListener('click', function () {
  if (i >= qs.length) return;
  if (document.getElementById('a').value === qs[i][1]) score++;
  i++;
  document.getElementById('s').textContent = '점수: ' + score;
  document.getElementById('q').textContent = i < qs.length ? qs[i][0] : '끝!';
});
</script>
</body>
