<head>
<meta charset="UTF-8">
<title>별 모으기</title>
</head>
<body>
<p id="s">점수: 0</p>
<canvas id="c" width="300" height="200"></canvas>
<script>
const ctx = document.getElementById('c').getContext('2d');
let px = 20, py = 20, sx = 200, sy = 120, score = 0;
function draw() { ctx.clearRect(0, 0, 300, 200); ctx.fillRect(px, py, 20, 20); ctx.fillText('★', sx, sy); }
document.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowRight') px += 10;
  if (e.key === 'ArrowLeft') px -= 10;
  if (e.key === 'ArrowUp') py -= 10;
  if (e.key === 'ArrowDown') py += 10;
  if (Math.abs(px - sx) < 20 && Math.abs(py - sy) < 20) { score++; sx = Math.random() * 280; sy = Math.random() * 180; }
  document.getElementById('s').textContent = '점수: ' + score;
  draw();
});
draw();
</script>
</body>
</html>
