<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<title>우주선</title>
</head>
<body>
<p id="s">점수: 0, 목숨: 3</p>
<canvas id="c" width="300" height="200"></canvas>
<script>
const ctx = document.getElementById('c').getContext('2d');
let px = 140, score = 0, lives = 3, run = true;
let rock = { x: 100, y: 0 };
document.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowLeft') { px = Math.max(0, px - 10); e.preventDefault(); }
  if (e.key === 'ArrowRight') { px = Math.min(280, px + 10); e.preventDefault(); }
});
setInterval(function () {
  if (!run) return;
  rock.y += 5;
  if (rock.y > 200) { rock.y = 0; rock.x = Math.random() * 280; score++; }
  if (Math.hypot(rock.x - px, rock.y - 180) < 20) { lives--; rock.y = 0; if (lives <= 0) run = false; }
  ctx.clearRect(0, 0, 300, 200);
  ctx.fillRect(px, 180, 20, 20);
  ctx.beginPath(); ctx.arc(rock.x, rock.y, 10, 0, Math.PI * 2); ctx.fill();
  document.getElementById('s').textContent = run ? '점수: ' + score + ', 목숨: ' + lives : '게임 오버';
}, 50);
</script>
</body>
</html>
